from taf.transport.ssh import ssh

from taf.ul.bts_components import Smod as SmodComponent


class Smod(object):
    """
    Representation of Smod parameters. Gets all necessary parameters from Smod and test line configuration file
    to set proper timeout for operations.
    """

    def __init__(self, smod, test_pc):
        self.test_pc = test_pc
        self.capacity_units = smod.capacity_units if hasattr(smod, 'capacity_units') else None
        self.rus = smod.rus if not hasattr(smod, 'capacity_units') else None
        self.hardware_type = smod.hardware_type
        self._smod_instance = SmodComponent()
        self._ssh = ssh()
        self._config = smod

    def connect_to_smod_via_its_test_pc(self, test_pc_alias="KPI_test_pc", smod_alias="KPI_SMOD"):
        """
        Connects to system module via its test pc.
        :param test_pc_alias: connection alias for test pc
        :type test_pc_alias: str
        :param smod_alias: connection alias for smod
        :type smod_alias: str
        """
        self._connect_to_vm_via_ssh(
            hostname=self.test_pc.default_ssh_connection_details.addr,
            username=self.test_pc.default_ssh_connection_details.username,
            password=self.test_pc.default_ssh_connection_details.password,
            alias=test_pc_alias
        )
        self._smod_instance.connect_to(
            address=self._config.lmp_connection.addr,
            username=self._config.lmp_connection.username,
            password=self._config.lmp_connection.password,
            proxy=test_pc_alias,
            alias=smod_alias
        )

    def close_connections(self, test_pc_alias="KPI_test_pc"):
        """
        Closes connections to smod and test pc
        :param test_pc_alias: connection alias for test pc
        :type test_pc_alias: str
        """
        self._smod_instance.close_connection()
        self._ssh.disconnect(connection=test_pc_alias)

    def get_rfsw_from_targetbd(self, rmod_type, rmod_protocol):
        """
        Gets rfsw for rmod from targetbd file
        :param rmod_type: type of rmod, e.g. AEQA
        :type rmod_type: str
        :param rmod_protocol: rmod protocol, e.g. CPRI
        :type rmod_protocol: str
        :return: rfsw for rmod
        :rtype: str
        """
        return self._smod_instance.get_rfsw_from_targetbd(rmod_type, rmod_protocol)

    def _connect_to_vm_via_ssh(self, hostname, username="ute", password="uteuteute", alias="admin_vm"):
        """
        Creates ssh connection to VM with proper hostname.
        :param hostname: VM ip address.
        :type hostname: str
        :param username: VM username. 'ute' at default.
        :type username: str
        :param password: VM password. 'uteuteute' at default.
        :type password: str
        :param alias: ssh connection alias. 'admin' at default.
        :type alias: str
        """
        self._ssh.connect_to(
            hostname=hostname, username=username, password=password, alias=alias
        )
